/usr/bin/bash -lc "node --input-type=module <<'EOF'
import fs from 'node:fs';
import vm from 'node:vm';
import assert from 'node:assert/strict';
const source = fs.readFileSync('src/editors/PersonnelEditor.vue', 'utf8');
const script = source.match(/<script>([\\s\\S]*?)<\\/script>/)[1].replace(/"'^import .*;$/gm, '"'').replace('export default', 'module.exports =');
const config = JSON.parse(fs.readFileSync('src/config/personnel-form.json', 'utf8'));
const context = { module: { exports: {} }, SchemaForm: {}, personnelConfig: config, Promise };
vm.runInNewContext(script, context);
const editor = context.module.exports;
const writes = [];
const instance = { ...editor.data(), parentNode: { id: 7, code: 'P', name: 'Parent' } };
for (const [name, method] of Object.entries(editor.methods)) instance[name] = method.bind(instance);
const pending = instance.getPageConfig();
assert.equal(instance.rule.length, 0);
instance.formApi = { setValue: value => writes.push(value) };
editor.watch.formApi.call(instance);
await pending;
assert.equal(instance.rule.length, 4);
assert.equal(instance.option.layout, 'compact');
assert.equal(writes.length, 1);
assert.equal(writes[0].parentId, 7);
instance.rule[3].on.search();
assert.equal(instance.pickerVisible, true);
await instance.getPageConfig();
assert.equal(writes.length, 2);
assert.equal(config.rule[3].on, undefined);
console.log('Personnel delayed readiness, parent values, picker, repeat load: passed');
EOF
